ResetDailyDrawdownState()
  {
//--- Mark the complete daily calculation as unavailable
g_dailyDrawdown.ready              =
false
;
   g_dailyDrawdown.referenceEquity    =
0.0
;
   g_dailyDrawdown.currentEquity      =
0.0
;
   g_dailyDrawdown.maximumDailyLoss   =
0.0
;
   g_dailyDrawdown.dailyEquityFloor   =
0.0
;
   g_dailyDrawdown.currentDailyLoss   =
0.0
;
